result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test_transaction_rollback.py", "content": """"An endpoint that raises mid-transaction:

- the partial write (debit done, credit never issued) is rolled back;
- the NEXT request gets a clean connection — no lingering transaction,
  no 'database is locked', correct balances.
"""

from __future__ import annotations


def _balances(client) -> dict[int, int]:
    resp = client.get("/accounts")
    assert resp.status_code == 200
    return {row["id"]: row["balance"] for row in resp.get_json()}


def test_mid_transaction_raise_rolls_back_partial_write(seeded):
    assert _balances(seeded) == {1: 100, 2: 0}

    # Debit of account 1 happens, then the endpoint raises before COMMIT.
    resp = seeded.post("/transfer?explode=1", json={"src": 1, "dst": 2, "amount": 70})
    assert resp.status_code == 500

    # The debit was discarded: balances are untouched.
    assert _balances(seeded) == {1: 100, 2: 0}


def test_next_request_after_crash_gets_a_clean_connection(seeded):
    seeded.post("/transfer?explode=1", json={"src": 1, "dst": 2, "amount": 70})

    # If teardown hadn't closed/rolled back the crashed request's connection,
    # this next write would either hang on a stale lock / hit
    # 'database is locked' / or see the dirty debit. It does none of those:
    resp = seeded.post("/transfer", json={"src": 1, "dst": 2, "amount": 25})
    assert resp.status_code == 200
    assert _balances(seeded) == {1: 75, 2: 25}

    # And several more clean writes in a row for good measure.
    for amount in (5, 10, 15):
        assert seeded.post("/transfer", json={"src": 2, "dst": 1, "amount": amount}).status_code == 200
    assert _balances(seeded) == {1: 105, 2: -5 + 25 - 30}


def test_success_path_commits_for_real(seeded):
    resp = seeded.post("/transfer", json={"src": 1, "dst": 2, "amount": 40})
    assert resp.status_code == 200
    assert _balances(seeded) == {1: 60, 2: 40}
